/* GroupInfoMapper.findByInviteCodeAndUseYn */
SELECT 
FROM group_info
WHERE invite_code = #{inviteCode} AND use_yn = #{useYn}

/* GroupInfoMapper.findByInviteCodeAndUseYnForUpdate */
SELECT 
FROM group_info
WHERE invite_code = #{inviteCode} AND use_yn = #{useYn}
FOR UPDATE

/* GroupInfoMapper.findByClaId */
SELECT 
FROM group_info
WHERE cla_id = #{claId}

/* GroupInfoMapper.findGroupInfoById */
SELECT 
FROM group_info
WHERE group_id = #{groupId}

/* GroupInfoMapper.findActiveGroupsByHostUserNo */
SELECT 
FROM group_info
WHERE host_user_no = #{hostUserNo}
  AND use_yn = 'Y'
ORDER BY created_at DESC

